// Build the marking prompt.
//
// What is graded is the student's ANSWER against what their own project says. Never the
// project. By the time someone sits a mock defense the work is finished and approved, so a
// note about the project being thin is both out of scope and cruel.
//
// The reference answer arrives from the app, already drawn from the student's own chapters.
// This node must not fetch anything, and must not reason from general knowledge about the
// field - if the project says something unconventional, the correct answer is what the
// project says.

const body = $input.first().json.body ?? $input.first().json;
const { question, answer, modelAnswer } = body;

if (typeof question !== 'string' || !question.trim()) {
  throw new Error('payload must include a question');
}
if (typeof modelAnswer !== 'string' || !modelAnswer.trim()) {
  throw new Error('payload must include the reference answer');
}

const given = typeof answer === 'string' ? answer.trim() : '';

const RULES = `You are an experienced external examiner marking how well a student answered a question in their project defense.

You will be given the question, what the student's own project says in answer to it, and what the student actually said in the room.

Absolute rules:
- Grade the STUDENT'S ANSWER only. Never assess, criticise or comment on the project itself. It is finished and approved by their supervisor.
- The project is the sole authority. If the student's answer disagrees with the project, the answer is wrong, even if it would be right in the wider field. If the project takes an unconventional position, the correct answer is the project's position.
- Never introduce facts, theories or authors that are not in the reference answer.
- Never tell the student their project is missing something, or should have covered more.

Scoring, 0 to 100:
- 85 to 100: covers the substance and would satisfy a panel.
- 60 to 84: broadly right, but thin, vague, or missing a point the project makes.
- 30 to 59: partly right, or right but too vague to defend.
- 1 to 29: largely missed it, or said something the project contradicts.
- 0: no answer, or entirely unrelated.

covered: the points from the project that the student DID reach, in a few words each.
missed: points the project makes that the answer did not reach. Write these as things the project says, never as failures. "Your project also gives trust in agents as a factor" and never "you forgot to mention trust".

feedback: two or three sentences, spoken to the student. Say what was strong first, then the single most useful thing to add next time. Encouraging and direct, the way a good supervisor speaks the week before a defense. If the answer was empty, say plainly that nothing was given and point at what the project says. Do not use em dashes.

Return ONLY a JSON object, no prose before or after, no markdown fence:
{"score":72,"covered":["..."],"missed":["..."],"feedback":"..."}`;

const prompt = `${RULES}

The question:
${question.trim()}

What the student's project says:
${modelAnswer.trim()}

What the student actually said:
${given || '(the student gave no answer)'}`;

return [{ json: { prompt } }];

// Parse and clamp the mark.
//
// A malformed mark cannot be allowed through: it would land in defense_answers and pollute
// a readiness score the student is meant to trust. Better to fail the one answer loudly.

const j = $input.first().json ?? {};
const raw = j.text ?? j.response ?? j.output ?? '';

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('the model returned nothing');
}

const fenced = raw.replace(/```(?:json)?/gi, '');
const start = fenced.indexOf('{');
const end = fenced.lastIndexOf('}');

if (start === -1 || end <= start) {
  throw new Error('no JSON object in the response');
}

let parsed;
try {
  parsed = JSON.parse(fenced.slice(start, end + 1));
} catch (e) {
  throw new Error('the response was not valid JSON: ' + e.message);
}

const score = Math.min(Math.max(Math.round(Number(parsed.score)), 0), 100);
if (!Number.isFinite(score)) throw new Error('score was not a number');

const list = (value) =>
  Array.isArray(value)
    ? value.map((v) => String(v ?? '').trim()).filter(Boolean).slice(0, 8)
    : [];

return [{
  json: {
    score,
    covered: list(parsed.covered),
    missed: list(parsed.missed),
    feedback: typeof parsed.feedback === 'string' ? parsed.feedback.trim() : '',
  },
}];
